def _code_mode_web_actions(
    payload: Mapping[str, object],
    line_number: int,
) -> frozenset[str]:
    call_id = payload.get("call_id")
    if not _valid_nonblank(call_id):
        raise PushValidationError(
            f"code-mode web call at rollout line {line_number} has an invalid call_id"
        )
    source = payload.get("input")
    if not isinstance(source, str):
        raise PushValidationError(f"code-mode web call {call_id} has unsupported input")
    if source.endswith("\n"):
        source = source[:-1]
    if not source.startswith(CODE_MODE_WEB_INPUT_PREFIX) or not source.endswith(
        CODE_MODE_WEB_INPUT_SUFFIX
    ):
        raise PushValidationError(f"code-mode web call {call_id} has unsupported input")

    arguments = source[
        len(CODE_MODE_WEB_INPUT_PREFIX) : -len(CODE_MODE_WEB_INPUT_SUFFIX)
    ]
    if not arguments.startswith("{") or not arguments.endswith("}"):
        raise PushValidationError(f"code-mode web call {call_id} has unsupported arguments")

    delimiters: list[str] = []
    top_level_keys: set[str] = set()
    expecting_top_level_key = False
    in_string = False
    escaped = False
    index = 0
    while index < len(arguments):
        character = arguments[index]
        if in_string:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == '"':
                in_string = False
            index += 1
            continue
        if (
            len(delimiters) == 1
            and delimiters[-1] == "{"
            and expecting_top_level_key
            and character == '"'
        ):
            try:
                key_value, key_length = json.JSONDecoder().raw_decode(arguments[index:])
            except json.JSONDecodeError as exc:
                raise PushValidationError(
                    f"code-mode web call {call_id} has malformed arguments"
                ) from exc
            if not isinstance(key_value, str):
                raise PushValidationError(
                    f"code-mode web call {call_id} has unsupported arguments"
                )
            key_end = index + key_length
            while key_end < len(arguments) and arguments[key_end].isspace():
                key_end += 1
            if key_end >= len(arguments) or arguments[key_end] != ":":
                raise PushValidationError(
                    f"code-mode web call {call_id} has unsupported arguments"
                )
            if key_value in top_level_keys:
                raise PushValidationError(
                    f"code-mode web call {call_id} has duplicate arguments"
                )
            top_level_keys.add(key_value)
            expecting_top_level_key = False
            index = key_end
        elif character == '"':
            in_string = True
        elif character in {"'", "`", "(", ")", ";"}:
            raise PushValidationError(
                f"code-mode web call {call_id} has unsupported arguments"
            )
        elif character in "{[":
            delimiters.append(character)
            if len(delimiters) == 1:
                expecting_top_level_key = True
        elif character in "}]":
            opener = "{" if character == "}" else "["
            if not delimiters or delimiters[-1] != opener:
                raise PushValidationError(
                    f"code-mode web call {call_id} has malformed arguments"
                )
            if (
                len(delimiters) == 1
                and expecting_top_level_key
                and top_level_keys
            ):
                raise PushValidationError(
                    f"code-mode web call {call_id} has malformed arguments"
                )
            delimiters.pop()
        elif len(delimiters) == 1 and delimiters[-1] == "{":
            if expecting_top_level_key:
                if character.isspace():
                    index += 1
                    continue
                key = CODE_MODE_WEB_KEY.match(arguments, index)
                if key is None:
                    raise PushValidationError(
                        f"code-mode web call {call_id} has unsupported arguments"
                    )
                key_end = key.end()
                while key_end < len(arguments) and arguments[key_end].isspace():
                    key_end += 1
                if key_end >= len(arguments) or arguments[key_end] != ":":
                    raise PushValidationError(
                        f"code-mode web call {call_id} has unsupported arguments"
                    )
                key_value = key.group()
                if key_value in top_level_keys:
                    raise PushValidationError(
                        f"code-mode web call {call_id} has duplicate arguments"
                    )
                top_level_keys.add(key_value)
                expecting_top_level_key = False
                index = key_end
            elif character == ",":
                expecting_top_level_key = True
        index += 1

    if in_string or delimiters:
        raise PushValidationError(f"code-mode web call {call_id} has malformed arguments")
    actions = frozenset(top_level_keys & ELIGIBLE_WEB_ACTIONS)
    if not actions:
        raise PushValidationError(f"code-mode web call {call_id} has no eligible action")
    return actions


def _code_mode_output_text_blocks(
    pair_call_id: str,
    output: object,
) -> tuple[str, ...]:
    if not isinstance(output, list) or len(output) != CODE_MODE_WEB_OUTPUT_BLOCK_COUNT:
        raise PushValidationError(
            f"code-mode web output {pair_call_id} has an unsupported payload"
        )
    blocks = _output_text_blocks(pair_call_id, output)
    status = blocks[CODE_MODE_WEB_STATUS_BLOCK_INDEX]
    result = blocks[CODE_MODE_WEB_RESULT_BLOCK_INDEX]
    if CODE_MODE_WEB_STATUS.fullmatch(status) is None or not result.strip():
        raise PushValidationError(
            f"code-mode web output {pair_call_id} has an unsupported payload"
        )
    return (result,)


def build_evidence_index(records: tuple[RolloutRecord, ...]) -> EvidenceIndex:
    calls: dict[str, RolloutRecord] = {}
    code_mode_calls: dict[str, RolloutRecord] = {}
    web_call_ids: set[str] = set()
    outputs: dict[str, list[RolloutRecord]] = {}
    code_mode_outputs: dict[str, list[RolloutRecord]] = {}
    events: dict[str, list[RolloutRecord]] = {}
    records_by_line = {record.line_number: record for record in records}

    for record in records:
        value = record.value
        payload = value.get("payload")
        if not isinstance(payload, dict):
            continue
        payload_type = payload.get("type")
        if (
            value.get("type") == "response_item"
            and payload_type == "function_call"
            and payload.get("namespace") == "web"
            and payload.get("name") == "run"
        ):
            arguments = _web_arguments(payload, record.line_number)
            call_id = cast(str, payload["call_id"])
            if call_id in web_call_ids:
                raise PushValidationError(f"duplicate web call_id {call_id}")
            web_call_ids.add(call_id)
            if not any(arguments.get(action) for action in ELIGIBLE_WEB_ACTIONS):
                continue
            calls[call_id] = record
        elif (
            value.get("type") == "response_item"
            and payload_type == "custom_tool_call"
            and payload.get("name") == "exec"
            and isinstance(payload.get("input"), str)
            and cast(str, payload["input"]).startswith(CODE_MODE_WEB_INPUT_PREFIX)
        ):
            _code_mode_web_actions(payload, record.line_number)
            call_id = cast(str, payload["call_id"])
            if call_id in web_call_ids:
                raise PushValidationError(f"duplicate web call_id {call_id}")
            web_call_ids.add(call_id)
            code_mode_calls[call_id] = record
        elif value.get("type") == "response_item" and payload_type == "function_call_output":
            output_call_id = payload.get("call_id")
            if not _valid_nonblank(output_call_id):
                raise PushValidationError(
                    f"function output at rollout line {record.line_number} has an invalid call_id"
                )
            output_call_id = cast(str, output_call_id)
            if output_call_id in outputs:
                raise PushValidationError(
                    f"duplicate function output call_id {output_call_id}"
                )
            outputs[output_call_id] = [record]
        elif (
            value.get("type") == "response_item"
            and payload_type == "custom_tool_call_output"
        ):
            output_call_id = payload.get("call_id")
            if _valid_nonblank(output_call_id):
                code_mode_outputs.setdefault(cast(str, output_call_id), []).append(record)
        elif value.get("type") == "event_msg" and payload_type == "web_search_end":
            event_call_id = payload.get("call_id")
            if not _valid_nonblank(event_call_id):
                raise PushValidationError(
                    f"web event at rollout line {record.line_number} has an invalid call_id"
                )
            events.setdefault(cast(str, event_call_id), []).append(record)

    pairs: list[EvidencePair] = []
    for call_id, call in sorted(calls.items(), key=lambda item: item[1].line_number):
        matching_outputs = outputs.get(call_id, [])
        if len(matching_outputs) != 1:
            reason = "missing" if not matching_outputs else "ambiguous"
            raise PushValidationError(f"eligible web output {call_id} is {reason}")
        output = matching_outputs[0]
        payload = cast(dict[str, object], output.value["payload"])
        pairs.append(
            EvidencePair(
                call_id=call_id,
                call=call,
                output=output,
                events=tuple(events.get(call_id, [])),
                text_blocks=_output_text_blocks(call_id, payload.get("output")),
            )
        )

    for call_id, call in sorted(
        code_mode_calls.items(), key=lambda item: item[1].line_number
    ):
        matching_outputs = code_mode_outputs.get(call_id, [])
        if len(matching_outputs) != 1:
            reason = "missing" if not matching_outputs else "ambiguous"
            raise PushValidationError(f"eligible code-mode web output {call_id} is {reason}")
        output = matching_outputs[0]
        event = records_by_line.get(call.line_number + CODE_MODE_WEB_EVENT_LINE_OFFSET)
        event_payload = event.value.get("payload") if event is not None else None
        if not (
            event is not None
            and event.value.get("type") == "event_msg"
            and isinstance(event_payload, dict)
            and event_payload.get("type") == "web_search_end"
            and _valid_nonblank(event_payload.get("call_id"))
            and event_payload.get("call_id") != call_id
        ):
            raise PushValidationError(
                f"eligible code-mode web event {call_id} is missing or malformed"
            )
        if output.line_number != call.line_number + CODE_MODE_WEB_OUTPUT_LINE_OFFSET:
            raise PushValidationError(
                f"eligible code-mode web output {call_id} is not adjacent"
            )
        payload = cast(dict[str, object], output.value["payload"])
        pairs.append(
            EvidencePair(
                call_id=call_id,
                call=call,
                output=output,
                events=(event,),
                text_blocks=_code_mode_output_text_blocks(
                    call_id,
                    payload.get("output"),
                ),
            )
        )

    return EvidenceIndex(tuple(sorted(pairs, key=lambda pair: pair.call.line_number)))


