    @model_validator(mode="after")
    def validate_field(self) -> Self:
        if not self.value.strip():
            raise ValueError("value must be non-blank")
        evidence_pairs = [
            (evidence.excerpt, evidence.url)
            for evidence in self.web_search_excerpts
